UPDATE public.rta_match m SET synergy_applied_at = CURRENT_TIMESTAMP, synergy_apply_result = 'S' FROM unnest(ARRAY[
#{rid}
]::bigint[]) AS u(rid) WHERE m.replay_id = u.rid

mapper.select:
WITH pool_filtered AS ( SELECT s.rank_position, s.wizard_id, s.wizard_name, s.country, s.channel_uid, s.score, s.rating_id, s.max_season_score, s.match_count, s.win_count FROM public.rta_agg_summoner_ranking_snap s WHERE s.season_id = #{seasonId}
AND ( CASE WHEN TRIM(COALESCE(s.country::text, '')) = '' THEN '—' ELSE TRIM(s.country::text) END ) = #{countryFilter}
), pool_meta AS ( SELECT COUNT(*)::int AS "rankingPoolTotal" FROM pool_filtered ), page AS ( SELECT * FROM pool_filtered ORDER BY rank_position LIMIT #{limit} OFFSET #{offset} ) SELECT pm."rankingPoolTotal", p.rank_position, p.wizard_id, p.wizard_name, p.country, p.channel_uid, p.score, p.rating_id, p.max_season_score, p.match_count, p.win_count FROM pool_meta pm LEFT JOIN page p ON true ORDER BY p.rank_position NULLS LAST
